    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Locate the full-width/full-height non-background divider.
    divider = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            divider = ('h', r, row[0])
            break
    if divider is None:
        for c in range(w):
            vals = {grid[r][c] for r in range(h)}
            if len(vals) == 1 and next(iter(vals)) != bg:
                divider = ('v', c, next(iter(vals)))
                break
    if divider is None:
        return [row[:] for row in grid]

    axis, pos, divider_color = divider
    obj_colors = [v for v in counts if v != bg and v != divider_color]
    if not obj_colors:
        return [row[:] for row in grid]
    obj_color = max(obj_colors, key=lambda v: counts[v])
    cells = [(r, c) for r in range(h) for c in range(w)
